import React, { useEffect } from "react";
import { Appearance, View, type ColorSchemeName, type ViewProps } from "react-native";
import { OverlayProvider } from "@gluestack-ui/core/overlay/creator";
import { ToastProvider } from "@gluestack-ui/core/toast/creator";

export type ModeType = "light" | "dark" | "system";

/**
 * Root provider for gluestack-ui (generated by `npx gluestack-ui init`). Sets the app's color
 * scheme from `mode` and hosts overlays (modals, popovers) and toasts. Wraps the app in App.tsx.
 */
export function GluestackUIProvider({
    mode = "system",
    ...props
}: {
    mode?: ModeType;
    children?: React.ReactNode;
    style?: ViewProps["style"];
}) {
    useEffect(() => {
        // Known gap (generated code): React Native 0.81 accepts "light", "dark" or null, so
        // mode="system" must map to null. Harmless while App.tsx passes "light"; dark mode (#52)
        // has to fix it.
        Appearance.setColorScheme(mode as ColorSchemeName);
    }, [mode]);

    return (
        <View style={[{ flex: 1, height: "100%", width: "100%" }, props.style]}>
            <OverlayProvider>
                <ToastProvider>{props.children}</ToastProvider>
            </OverlayProvider>
        </View>
    );
}
